function renderPriority(){const rows=ranked();$('#analysisContent').innerHTML=`<section class="panel"><div class="section-heading"><div><h2>구조물별 점검 우선순위</h2><p>P = 0.30Q + 0.25M + 0.25D + 0.20E · 현재 설정의 정규화된 가중치를 적용합니다.</p></div><button class="secondary" id="weightsButton">가중치·민감도 설정</button></div><div class="analysis-controls"><label>구조물 유형 <select id="typeFilter"><option value="all">전체</option>${Object.entries(G.types).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>최소 점수 <input id="minScore" type="number" min="0" max="100" value="0"></label><button class="secondary" id="priorityFilter">필터 적용</button></div><div id="priorityTable"></div></section><div class="notice">Q·M은 가상 시공·자재 지표, D는 현재 시점의 직접·인접 결함과 미완료 요청, E는 외벽·저층 노출과 환경 시나리오를 반영합니다. 값이 높을수록 먼저 살펴볼 대상이라는 의미입니다.</div>`;function table(){const type=$('#typeFilter').value,min=G.clamp(+$('#minScore').value);$('#priorityTable').innerHTML=`<div class="table-scroll"><table><thead><tr><th>순위</th><th>구조물 / ID</th><th>Q 시공</th><th>M 자재</th><th>D 이력</th><th>E 환경</th><th>우선도</th><th>분류</th></tr></thead><tbody>${rows.filter(r=>(type==='all'||r.e.type===type)&&r.value>=min).map((r,i)=>`<tr><td>${i+1}</td><td><button data-select="${esc(r.e.id)}">${esc(r.e.name)} ↗</button><small>${esc(r.e.id)}</small></td>${['Q','M','D','E'].map(k=>`<td>${Math.round(r.factors[k])}</td>`).join('')}<td><b>${r.value}</b></td><td><span class="pill">${status(r.value)}</span></td></tr>`).join('')}</tbody></table></div>`}table();$('#priorityFilter').onclick=table;$('#weightsButton').onclick=weightForm}
function renderHotspots(){const rows=G.hotspots(model,{asOf:options.asOf,requests,group:hotspotGroup}),max=Math.max(1,...rows.map(r=>r.count));const months=Array.from({length:10},(_,i)=>`2026-${String(i+1).padStart(2,'0')}-${i===9?'30':new Date(2026,i+1,0).getDate()}`),counts=months.map(date=>G.activeDefects(model,date).length),cmax=Math.max(1,...counts);$('#analysisContent').innerHTML=`<div class="bottom-grid" style="margin-top:0"><section class="panel"><div class="section-heading"><div><h2>공간별 신고·결함 집중 구역</h2><p>밀도 통계 검정이 아닌 구역별 건수 집계입니다.</p></div><select id="groupSelect" aria-label="분포 집계 기준"><option value="floor" ${hotspotGroup==='floor'?'selected':''}>층별</option><option value="material" ${hotspotGroup==='material'?'selected':''}>동일 자재별</option><option value="direction" ${hotspotGroup==='direction'?'selected':''}>외벽 방향별</option></select></div><div class="content-pad">${rows.map(r=>`<div class="chart-row"><span>${esc(r.key)}</span><div class="track"><i style="width:${r.count/max*100}%"></i></div><b>${r.count}</b></div>`).join('')||'<div class="empty">해당 시점의 이력이 없습니다.</div>'}<p class="graph-note">${options.asOf} 기준 · 결함 이력 + 미완료 요청 건수. 중복 신고와 결함은 각각 집계합니다.</p></div></section><section class="panel"><div class="section-heading"><div><h2>시점별 활성 결함 이력</h2><p>발생일·보수 종료일에 따른 월말 상태</p></div></div><div class="content-pad"><svg class="chart-svg" viewBox="0 0 430 190" role="img" aria-label="1월부터 10월까지 월별 활성 결함 건수">${counts.map((n,i)=>`<rect x="${22+i*40}" y="${150-n/cmax*110}" width="22" height="${n/cmax*110}" rx="3" fill="${i===9?'#739567':'#c3d2b4'}"/><text x="${33+i*40}" y="${140-n/cmax*110}" text-anchor="middle" font-size="9" fill="#96aa84">${n}</text><text x="${33+i*40}" y="173" text-anchor="middle" font-size="9" fill="#9aaf86">${i+1}월</text>`).join('')}</svg><p class="graph-note">모델 결함 이력만 표시합니다. 현재 요청 상태를 과거 상태로 재구성하지는 않습니다.</p></div></section></div><section class="panel" style="margin-top:20px"><div class="section-heading"><div><h2>가상 결함·보수 타임라인</h2><p>종료된 이력도 보존해 반복 발생과 보수 시점을 비교합니다.</p></div></div><div class="table-scroll"><table><thead><tr><th>공간 ID</th><th>기록 유형</th><th>발생일</th><th>종료일</th><th>선택 시점 상태</th></tr></thead><tbody>${model.defects.map(d=>`<tr><td><button data-select="${esc(d.element)}">${esc(d.element)} ↗</button></td><td>${esc(d.type)}</td><td>${d.date}</td><td>${d.closed||'미종료'}</td><td>${d.date>options.asOf?'발생 전':d.closed&&d.closed<=options.asOf?'종료':'활성'}</td></tr>`).join('')}</tbody></table></div></section>`;$('#groupSelect').onchange=e=>{hotspotGroup=e.target.value;renderHotspots()}}
function renderEnvironment(){const facade=model.elements.filter(e=>e.direction),avg=facade.length?Math.round(facade.reduce((n,e)=>n+calc(e).factors.E,0)/facade.length):0;$('#analysisContent').innerHTML=`<div class="environment-grid" style="margin-top:0"><section class="panel"><div class="section-heading"><div><h2>외부 환경 노출 개념 지도</h2><p>로컬 좌표의 가상 지형·강우 시나리오 · 실제 위치 및 외부 GIS API 미연결</p></div></div><div class="terrain"><svg viewBox="0 0 650 280" aria-label="가상 지형과 건물 노출 개념도"><path d="M0 240Q160 70 300 220T650 100V280H0Z" fill="#e0ead3"/><path d="M0 250Q190 100 330 240T650 120" fill="none" stroke="#c6d8b4"/><path d="M0 225Q160 40 300 200T650 70" fill="none" stroke="#d0dfc1"/><path d="M370 0Q300 150 460 280" stroke="#d7e7dc" stroke-width="50" fill="none"/><path d="M370 0Q300 150 460 280" stroke="#c1dacf" stroke-width="2" fill="none"/><path d="M120 180l170-55 160 70-170 57Z" fill="#ccdbb9" stroke="#adc594"/><path d="M220 183v-90l99-31v89Z" fill="#9bb88c"/><path d="M319 62l65 30v90l-65-31Z" fill="#b3c7a0"/><path d="M220 93l65 30 99-31-65-30Z" fill="#d2dfbe"/><text x="250" y="155" font-size="12" fill="#f5f9ee">A동</text><text x="442" y="54" font-size="10" fill="#a4b592">가상 수계 / 지형</text><path d="M480 80l-24 50m35-32-24 50m37-35-24 50" stroke="#98b7a2" stroke-width="2" opacity="${options.rain/100}"/><text x="34" y="38" font-size="9" fill="#9aae87">LOCAL ENVIRONMENT SCENARIO</text><text x="430" y="240" font-size="9" fill="#9aae87">실제 침수 위험지도 아님</text></svg></div><div class="content-pad"><p class="graph-note">환경 노출 지표 E만 조정합니다. 시나리오 값은 임의의 0~100 강도이며 실제 mm·W/m² 관측값이 아닙니다.</p></div></section><section class="panel"><div class="section-heading"><div><h2>환경 조건 조정</h2><p>가정한 환경 강도가 외벽·저층 점수에 미치는 영향을 비교합니다.</p></div></div><div class="content-pad"><label class="field">강우 시나리오 강도 <b id="rainValue">${options.rain}</b> / 100<input id="rain" type="range" min="0" max="100" value="${options.rain}"></label><label class="field">일사 노출 시나리오 <b id="sunValue">${options.sun}</b> / 100<input id="sun" type="range" min="0" max="100" value="${options.sun}"></label><div class="notice">외벽 E = 기본 E + 강우 × 0.35 + 일사 × 0.10<br>1층 바닥 E = 기본 E + 강우 × 0.20<br>최종 E는 0~100으로 제한합니다.</div><button class="primary" id="applyEnvironment">환경 조건 적용</button></div></section></div><div class="metric-grid"><div class="metric-card"><label>가정 강우 강도</label><strong>${options.rain}</strong><p>관측 데이터가 아닌 조정 가능한 시나리오 변수</p></div><div class="metric-card"><label>외벽 평균 환경 노출 E</label><strong>${avg}</strong><p>외벽 방향 속성이 있는 ${facade.length}개 구조물 평균</p></div><div class="metric-card"><label>현재 우선 검토 대상</label><strong>${ranked().filter(r=>r.value>=60).length}개</strong><p>변경한 E가 통합 점검 우선도에 반영됩니다.</p></div></div>`;$('#rain').oninput=e=>$('#rainValue').textContent=e.target.value;$('#sun').oninput=e=>$('#sunValue').textContent=e.target.value;$('#applyEnvironment').onclick=()=>{options.rain=+$('#rain').value;options.sun=+$('#sun').value;render();notify('환경 노출과 우선순위를 다시 계산했습니다.')}}
function renderValidation(){const e=current(),related=getCandidates().map(r=>r.element.id),baseline=model.elements.filter(b=>b.id!==e.id&&G.centerDistance(e,b)<=distanceRadius).map(e=>e.id),validReference=reference.filter(id=>model.elements.some(e=>e.id===id)),a=G.evaluate(related,validReference),b=G.evaluate(baseline,validReference);$('#analysisContent').innerHTML=`<section class="panel"><div class="section-heading"><div><h2>공간 관계 분석과 단순 거리 탐색 비교</h2><p>${esc(selected)} 기준 · 합성 기준 집합과의 겹침 비교</p></div><button class="text-button" data-tab="relations">기준 구조물 변경 ↗</button></div><div class="content-pad"><div class="notice">아래 기준 집합은 기능 시연용 가정입니다. 실제 현장 정답이나 모델 성능 검증 결과가 아닙니다. 동일한 기준을 두 방법에 적용해 차이를 비교합니다.</div><div class="analysis-controls" style="padding-left:0"><label>중심점 거리 반경 <input id="distanceRadius" type="number" min=".1" max="30" step=".1" value="${distanceRadius}"> m</label><button class="secondary" id="applyComparison">비교 다시 계산</button></div><h2>검토 기준 집합 선택</h2><div class="reference-options">${model.elements.filter(e=>e.id!==selected&&(G.distance(current(),e)<=4||validReference.includes(e.id))).slice(0,40).map(e=>`<label><input type="checkbox" data-reference="${esc(e.id)}" ${validReference.includes(e.id)?'checked':''}> ${esc(e.id)}</label>`).join('')}</div><div class="table-scroll" style="padding:0"><table><thead><tr><th>방법</th><th>후보 수</th><th>TP / FP / FN</th><th>Precision</th><th>Recall</th></tr></thead><tbody>${[['공간 관계 + 배관 연결',related,a],['단순 중심점 거리',baseline,b]].map(([n,ids,v])=>`<tr><td>${n}</td><td>${ids.length}</td><td>${v.tp} / ${v.fp} / ${v.fn}</td><td>${(v.precision*100).toFixed(1)}%</td><td>${(v.recall*100).toFixed(1)}%</td></tr>`).join('')}</tbody></table></div><p class="graph-note">TP: 후보∩기준 · FP: 후보−기준 · FN: 기준−후보. 기준이 비어 있으면 수치는 의미가 없습니다. 외부 현장 데이터로 별도 검증해야 합니다.</p><div class="bottom-grid"><div><h2>공간 관계 기반 후보</h2>${related.map(id=>`<span class="pill">${esc(id)}</span>`).join('')||'<p>없음</p>'}</div><div><h2>거리 기반 후보</h2>${baseline.map(id=>`<span class="pill">${esc(id)}</span>`).join('')||'<p>없음</p>'}</div></div></div></section>`;$('#applyComparison').onclick=()=>{const r=+$('#distanceRadius').value;if(!Number.isFinite(r)||r<=0||r>30)return notify('반경은 0 초과 30m 이하로 입력하세요.');distanceRadius=r;reference=[...$('#analysisContent').querySelectorAll('[data-reference]:checked')].map(e=>e.dataset.reference);renderValidation()}}
function weightForm(){const w={...options.weights},sum=()=>Object.values(w).reduce((a,b)=>a+b,0);show(`<div class="eyebrow">INSPECTION MODEL · SENSITIVITY</div><h2>점검 우선도 가중치 조정</h2><p>입력한 비율은 합계로 나누어 정규화합니다. 구조 안전 등급을 계산하는 모델이 아닙니다.</p>${[['Q','시공 품질·검사 이상'],['M','자재·설계 불일치'],['D','직접·인접 결함 이력'],['E','환경 노출·공간 조건']].map(([k,n])=>`<div class="weight-row"><span>${k}</span><input type="range" min="0" max="100" value="${Math.round(w[k]*100)}" data-weight="${k}" aria-label="${n} 가중치"><b id="weight-${k}">${Math.round(w[k]*100)}%</b></div>`).join('')}<div class="notice" id="weightPreview"></div><div class="dialog-actions"><button class="outline-button" id="resetWeights">기본값 30/25/25/20</button><button class="primary" id="applyWeights">가중치 적용</button></div>`);function update(){const factors=calc(current()).factors,s=sum();$('#weightPreview').textContent=s?`현재 선택 ${selected} · 가정 점수 ${(['Q','M','D','E'].reduce((n,k)=>n+factors[k]*w[k]/s,0)).toFixed(1)} · 입력 비율 합 ${Math.round(s*100)}%`:'가중치 합이 0입니다. 하나 이상 지정하세요.'}$('#dialogContent').querySelectorAll('[data-weight]').forEach(i=>i.oninput=()=>{w[i.dataset.weight]=+i.value/100;$('#weight-'+i.dataset.weight).textContent=i.value+'%';update()});$('#resetWeights').onclick=()=>{Object.assign(w,G.weights);$('#dialogContent').querySelectorAll('[data-weight]').forEach(i=>{i.value=Math.round(w[i.dataset.weight]*100);$('#weight-'+i.dataset.weight).textContent=i.value+'%'});update()};$('#applyWeights').onclick=()=>{if(!sum())return notify('가중치 합은 0보다 커야 합니다.');options.weights={...w};close();render();notify('정규화한 가중치를 모든 구조물에 적용했습니다.')};update()}
function elementDetails(){const e=current(),s=calc(e),ds=model.defects.filter(d=>d.element===selected),rs=requests.filter(r=>r.element===selected);show(`<div class="eyebrow">SPATIAL ELEMENT / ${esc(e.id)}</div><h2>${esc(e.name)} · 공간 이력</h2><dl class="kv"><dt>공간 ID</dt><dd>${esc(e.id)}</dd><dt>형상 범위 m</dt><dd>MIN ${e.min.map(n=>n.toFixed(2)).join(', ')}<br>MAX ${e.max.map(n=>n.toFixed(2)).join(', ')}</dd><dt>자재 / 제조사</dt><dd>${esc(e.material)} / ${esc(e.manufacturer||'미연결')}</dd><dt>규격</dt><dd>${esc(e.spec||'미연결')}</dd><dt>시공 / 검사</dt><dd>${esc(e.constructed||'미연결')} / ${esc(e.inspected||'미연결')}</dd><dt>현재 지표</dt><dd>Q ${s.factors.Q} · M ${s.factors.M} · D ${s.factors.D} · E ${s.factors.E.toFixed(1)}</dd></dl><h2>결함·보수 이력</h2>${ds.map(d=>`<p>${d.date} · ${esc(d.type)} · ${d.closed?'종료 '+d.closed:'미종료'}</p>`).join('')||'<p>연결된 모델 결함 이력 없음</p>'}<h2>유지관리 요청 연결</h2>${rs.map(r=>`<p>${esc(r.id)} · ${esc(r.title)} · 상태 ${['접수','담당자 배정','점검','보수 예정','보수 완료','확인 완료'][r.stage]}</p>`).join('')||'<p>현재 브라우저의 연결된 요청 없음</p>'}<div class="dialog-actions"><button class="outline-button" id="editElement">자재·검사 지표 편집</button><button class="primary" id="makeElementTask">이 위치에 점검 요청</button></div>`);$('#editElement').onclick=editElement;$('#makeElementTask').onclick=createTask}
function editElement(){const e=current();show(`<div class="eyebrow">ELEMENT PROPERTIES</div><h2>${esc(e.id)} 속성 편집</h2><form id="elementForm"><div class="form-grid"><label class="field">자재 그룹<input id="editMaterial" value="${esc(e.material)}" maxlength="100" required></label><label class="field">제조사<input id="editManufacturer" value="${esc(e.manufacturer||'')}" maxlength="100"></label><label class="field">규격<input id="editSpec" value="${esc(e.spec||'')}" maxlength="150"></label><label class="field">시공 날짜<input type="date" id="editConstructed" value="${esc(e.constructed||'')}"></label><label class="field">검사 날짜<input type="date" id="editInspected" value="${esc(e.inspected||'')}"></label><label class="field">Q · 검사 이상 지표 (0~100)<input type="number" min="0" max="100" step="1" required id="editQ" value="${e.Q}"></label><label class="field">M · 자재 불일치 지표 (0~100)<input type="number" min="0" max="100" step="1" required id="editM" value="${e.M}"></label><label class="field">E · 기본 환경 노출 (0~100)<input type="number" min="0" max="100" step="1" required id="editE" value="${e.E}"></label></div><div class="notice">연구용 입력 지표입니다. 시공 기록을 자동 검증하지 않습니다. 변경 후 점검 우선도가 다시 계산됩니다.</div><div class="dialog-actions"><button class="primary">속성 저장·다시 계산</button></div></form>`);$('#elementForm').onsubmit=event=>{event.preventDefault();const next=G.clone(model),x=next.elements.find(x=>x.id===selected);(x.revisions??=[]).push({material:x.material,Q:x.Q,M:x.M,E:x.E,at:new Date().toISOString()});Object.assign(x,{material:$('#editMaterial').value.trim(),manufacturer:$('#editManufacturer').value.trim(),spec:$('#editSpec').value.trim(),constructed:$('#editConstructed').value||null,inspected:$('#editInspected').value||null,Q:+$('#editQ').value,M:+$('#editM').value,E:+$('#editE').value});if(persist(next)){close();render();notify('속성과 수정 이력을 저장하고 점수를 다시 계산했습니다.')}}}
function createTask(){const e=current();show(`<div class="eyebrow">SPATIAL ANALYSIS → OPERATIONS</div><h2>분석 위치에서 점검 요청 만들기</h2><p>${esc(e.id)} · ${esc(e.name)}<br>요청은 기존 유지관리 워크스페이스의 같은 공간 ID와 연결됩니다.</p><form id="taskForm"><label class="field">점검 요청 제목<input id="taskTitle" required maxlength="80" value="${esc(e.name)} 공간 관계 기반 점검"></label><label class="field">점검 근거<textarea required id="taskNote" maxlength="1500">선택 요소 ${esc(e.id)}의 점검 우선도 ${calc(e).value}점. 관계 후보: ${getCandidates().slice(0,8).map(r=>esc(r.element.id)).join(', ')}. 분석은 점검 후보 선정용이며 원인은 현장에서 확인해야 합니다.</textarea></label><div class="notice">현재 브라우저에만 저장되는 데모 요청입니다. 실제 관리사무소로 전송되지 않습니다.</div><div class="dialog-actions"><button class="primary">유지관리 요청 등록</button></div></form>`);$('#taskForm').onsubmit=event=>{event.preventDefault();try{let ops=JSON.parse(localStorage.getItem(OPS_KEY));if(!ops){notify('유지관리 워크스페이스에서 가상 데이터를 먼저 초기화합니다.');ops=null}if(!ops){const seedScript=document.createElement('script');seedScript.src='build-model.js';seedScript.onload=()=>saveTask(BuildModel.seed());document.head.append(seedScript)}else saveTask(ops)}catch(error){notify('유지관리 데이터가 손상되어 저장하지 못했습니다. 기존 데이터를 확인하세요.')}};function saveTask(ops){try{if(ops.version!==2||!Array.isArray(ops.requests))throw Error('지원하지 않는 유지관리 데이터입니다.');const title=$('#taskTitle').value.trim(),description=$('#taskNote').value.trim();if(!title||!description)throw Error('제목과 점검 근거를 입력하세요.');const id='REQ-'+new Date().getFullYear()+'-'+crypto.randomUUID().slice(0,8).toUpperCase(),now=new Date().toLocaleString('sv-SE',{timeZone:'Asia/Seoul'}).replace(' ','T');ops.requests.unshift({id,unit:e.unit,space:e.type==='ceiling'?'bedroom':e.type==='floor'?'living':'bedroom',element:e.id,zone:e.direction?e.direction+' 외벽':'공간 분석 구역',type:'기타',title,description,stage:0,assignee:'',date:'',created:now,before:[],after:[],events:[{at:now,text:'Geo-BIM 공간 분석에서 생성 · 현장 검증 전',by:'전문가'}]});ops.notices.unshift({id:'N-'+Date.now(),unit:e.unit,at:now,text:id+' 공간 분석 기반 점검 요청 등록'});localStorage.setItem(OPS_KEY,JSON.stringify(ops));readRequests();options.requests=requests;close();render();notify(id+' 등록 완료 · 유지관리 메뉴에서 확인하세요.')}catch(error){notify(error.name==='QuotaExceededError'?'브라우저 저장 공간이 부족합니다.':error.message)}}}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportDialog(){show(`<div class="eyebrow">RESEARCH EXPORT</div><h2>공간 분석 결과 내보내기</h2><p>분석 시점, 가중치, 관계 설정, 가정한 환경 조건과 함께 결과를 저장합니다. 관리 요청의 사진·비공개 전문가 원문은 포함하지 않습니다.</p><div class="notice">${esc(model.name)} · ${model.elements.length}개 구조물<br>시점 ${options.asOf} · 선택 ${esc(selected)}<br>기하 경계 상자 기반 연구용 분석 · 실제 안전성 평가 아님</div><div class="dialog-actions"><button class="outline-button" id="modelExport">공간 모델 JSON</button><button class="outline-button" id="reportExport">분석 근거 JSON</button><button class="primary" id="csvExport">점검 우선순위 CSV</button></div>`);$('#modelExport').onclick=()=>download('build-intelligence-spatial-model.json',JSON.stringify(model,null,2),'application/json');$('#reportExport').onclick=()=>download('build-intelligence-analysis.json',JSON.stringify({dataType:'research-demo-not-safety-assessment',model:model.name,asOf:options.asOf,selected,weights:options.weights,environment:{rain:options.rain,sun:options.sun},relationshipOptions:relationOptions,candidates:getCandidates(),ranking:ranked().map(r=>({id:r.e.id,score:r.value,factors:r.factors}))},null,2),'application/json');$('#csvExport').onclick=()=>{const cell=v=>'"'+(/^[=+\-@\t\r]/.test(String(v))?"'":'')+String(v??'').replaceAll('"','""')+'"';const rows=[['공간 ID','층','유형','자재','Q','M','D','E','우선도','분석일'],...ranked().map(r=>[r.e.id,r.e.floor,G.types[r.e.type],r.e.material,...['Q','M','D','E'].map(k=>r.factors[k]),r.value,options.asOf])];download('build-intelligence-priorities.csv','\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}}
function importDialog(){show(`<div class="eyebrow">MODEL & DATA WORKSPACE</div><h2>공간 모델 가져오기</h2><p>현재 모델을 교체하기 전 먼저 JSON으로 내보내 보관하세요. 입력 데이터는 서버로 전송하지 않습니다.</p><div class="notice"><b>JSON</b> · 로컬 미터 XYZ 경계 상자, 구조물 ID, 유형, 층, Q·M·E, 결함 이력, 배관 연결.<br><b>IFC STEP 제한 지원</b> · IFCWALL/SLAB/COLUMN/BEAM/PIPESEGMENT/COVERING의 직접 사각형·원형 압출. 배치 변환 후 AABB를 계산합니다. BREP·CSG·매핑 형상·임의 단면은 제외됩니다. 자재·검사·배관 연결은 자동 추출하지 않으며 층은 3.2m 간격으로 추정합니다.</div><label class="field">JSON 또는 IFC 파일<input id="modelFile" type="file" accept=".json,.ifc"><small>최대 8MB · 500개 구조물 · 업로드 대신 브라우저에서 읽기</small></label><div id="importResult"></div><div class="dialog-actions"><button class="outline-button" id="sampleJSON">예시 JSON 다운로드</button><a class="secondary" href="sample-model.ifc" download style="text-decoration:none">지원 형식 IFC 예시</a><button class="primary" id="readModel">파일 읽기·검사</button></div><div id="confirmImportArea"></div>`);let pending=null;$('#sampleJSON').onclick=()=>download('example-spatial-model.json',JSON.stringify(G.seed(),null,2),'application/json');$('#readModel').onclick=async()=>{try{const f=$('#modelFile').files[0];if(!f)throw Error('파일을 선택하세요.');if(f.size>8e6)throw Error('8MB 이하 파일을 선택하세요.');const text=await f.text();let result;if(f.name.toLowerCase().endsWith('.ifc'))result=G.parseIFC(text);else result={model:G.validate(JSON.parse(text)),warnings:[],imported:0,total:0};pending=result.model;$('#importResult').innerHTML=`<div class="notice">검사 완료 · ${pending.elements.length}개 구조물 · ${pending.defects.length}개 결함 이력${result.total?`<br>IFC 대상 ${result.total}개 중 ${result.imported}개 형상 처리 · 나머지 제외`:''}<br>IFC 기본 Q/M=50, E=25는 미측정 기본값입니다.</div>${result.warnings.length?`<div class="import-results">${result.warnings.map(x=>esc(x)).join('<br>')}</div>`:''}`;$('#confirmImportArea').innerHTML='<div class="dialog-actions"><button class="primary" id="confirmImport">검사한 모델로 교체</button></div>';$('#confirmImport').onclick=()=>{if(persist(pending)){selected=model.elements[0].id;reference=[];floor=0;zoom=1;close();render();notify('공간 모델을 교체했습니다. 유지관리 기록은 보존됩니다.')}}}catch(error){pending=null;$('#confirmImportArea').innerHTML='';$('#importResult').innerHTML=`<div class="notice">${esc(error.message)}</div>`}}}
function methodology(){show(`<div class="eyebrow">METHOD & SCOPE · RESEARCH DEMO</div><h2>공간 취약성 분석의 기준과 범위</h2><p><b>기본 모델</b>은 가상 공동주택 4개 층·12개 호실·84개 구조물입니다. 실제 BIM이나 지리 좌표와 연결되지 않은 로컬 XYZ 미터 좌표를 사용합니다. 3D 화면은 경계 상자의 꼭짓점을 투영하며 회전·확대·구조물 선택을 지원합니다.</p><p><b>공간 관계</b>는 AABB 경계 상자의 세 축 중첩으로 교차, 경계 간 유클리드 거리로 인접을 계산합니다. XY 범위가 겹치고 층 차가 1이며 수직 간격이 허용 거리 이내인 구조물을 상하층 후보로 봅니다. 연결된 배관 ID는 명시적인 그래프에서 0~3단계 탐색합니다. 실제 물 흐름·결함 전파를 추정하는 물리 모델이 아닙니다.</p><p><b>점검 우선도</b> P=0.30Q+0.25M+0.25D+0.20E. Q·M·기본 E는 가상 입력입니다. D=min(100, 직접 활성 결함×38 + 인접 활성 결함×12 + 미완료 요청×20). E는 외벽에 강우×0.35+일사×0.10, 1층 바닥에 강우×0.20을 더하며 0~100으로 제한합니다. 변경한 가중치는 합으로 정규화합니다. 35점 미만 정기, 35~59점 관찰, 60점 이상 우선 검토는 데모 기준입니다.</p><p><b>시점</b>은 결함의 발생일·종료일과 요청의 등록일에 적용합니다. Q·M 기초값과 요청의 현재 처리 상태는 과거 상태로 재구성하지 않습니다. 외부 환경은 실제 관측값이 아닌 0~100의 가정 강도입니다. 분포는 구역별 집계이며 통계적 핫스폿 검정이 아닙니다.</p><p><b>IFC</b>는 직접 표현된 단순 사각형·원형 압출의 경계 상자만 지원합니다. 부분 가져오기 시 제외 항목을 표시합니다. IFC 좌표는 로컬 길이 단위만 적용하고 지도 좌표 변환·자재·검사·연결망을 자동 연결하지 않습니다. 품질 지표 기본값은 실제 평가값이 아닙니다.</p><p><b>서비스 범위</b>는 브라우저 저장 기반 데모입니다. 기존 관리 화면의 역할 전환은 실제 인증 경계가 아닙니다. AI 설명은 사전 기반이며 LLM·YOLO·실시간 센서·PostGIS 서버는 연결하지 않았습니다. 실제 점검 자료로 가중치와 분석 결과를 검증해야 합니다.</p>`)}
$('#navigation').onclick=e=>{const b=e.target.closest('[data-tab]');if(b){tab=b.dataset.tab;if(tab==='relations')colorLayer='relations';render()}};document.addEventListener('click',e=>{const b=e.target.closest('[data-tab],[data-select]');if(b?.dataset.tab&&b.closest('#analysisContent')){tab=b.dataset.tab;render()}if(b?.dataset.select){if(!['twin','relations'].includes(tab))tab='twin';select(b.dataset.select)}});document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-select][role="button"]'))e.target.click()});$('#importButton').onclick=importDialog;$('#dataButton').onclick=importDialog;$('#exportButton').onclick=exportDialog;$('#methodButton').onclick=methodology;$('#scopeButton').onclick=methodology;$('#projectInfo').onclick=()=>notify(model.name+' · '+model.elements.length+'개 구조물 · LOCAL_METERS');window.addEventListener('storage',e=>{if(e.key===OPS_KEY){readRequests();render()}});render();

